// Reads rules/eslint-boundaries.compiled.json (generated by tools/rules-engine; data only) and turns the frontend
// modules' mayDependOn / mustNotDependOn into feature-to-feature boundary policies. Never parses YAML.

import { existsSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { ElementTypes, FEATURE_CAPTURE } from './element-types.mjs';

/** Where the rules engine writes the boundary data, relative to the repository root. */
export const COMPILED_RULES_RELATIVE_PATH = join('rules', 'eslint-boundaries.compiled.json');

/** The compiled schema version this reader understands. */
export const SUPPORTED_SCHEMA_VERSION = 1;

const ANGULAR_KIND = 'angular';
const FEATURES_SEGMENT = `/${ElementTypes.features}/`;

/**
 * The compiled rules file found by walking up from `startDirectory`, or null when there is none (a project outside
 * the starter layout gets the default policies only).
 */
export function findCompiledRules(startDirectory) {
  let current = resolve(startDirectory);
  for (;;) {
    const candidate = join(current, COMPILED_RULES_RELATIVE_PATH);
    if (existsSync(candidate)) return candidate;
    const parent = dirname(current);
    if (parent === current) return null;
    current = parent;
  }
}

/**
 * Loads and checks the compiled data.
 * @throws Error when the file is not JSON or carries an unsupported schema version (stale ng-tools against a newer
 *   rules engine must fail loudly, not lint with half the rules).
 */
export function loadCompiledRules(path) {
  const data = JSON.parse(readFileSync(path, 'utf8'));
  if (data?.schemaVersion !== SUPPORTED_SCHEMA_VERSION) {
    throw new Error(`${path}: schemaVersion ${data?.schemaVersion} is not supported (expected ${SUPPORTED_SCHEMA_VERSION}).`);
  }
  if (!Array.isArray(data.modules)) throw new Error(`${path}: "modules" must be an array.`);
  return data;
}

/** The feature folder of a frontend module path (`.../features/<name>`), or null when it is not a feature. */
export function featureFolderOf(modulePath) {
  const path = `/${String(modulePath).replaceAll('\\', '/').replace(/\/+$/, '')}`;
  const at = path.lastIndexOf(FEATURES_SEGMENT);
  if (at < 0) return null;
  const rest = path.slice(at + FEATURES_SEGMENT.length);
  return rest !== '' && !rest.includes('/') ? rest : null;
}

/**
 * Feature-to-feature policies: a feature module may import another feature module only when its rules list it in
 * `mayDependOn`; `mustNotDependOn` is an explicit disallow that wins over any allow.
 */
export function featurePolicies(compiled) {
  const features = new Map();
  for (const module of compiled.modules) {
    if (module.kind !== ANGULAR_KIND) continue;
    const folder = featureFolderOf(module.path);
    if (folder !== null) features.set(module.module, { ...module, folder });
  }
  const policies = [];
  for (const feature of features.values()) {
    const targets = (names) => names.map((name) => features.get(name)?.folder).filter((folder) => folder !== undefined);
    const allowed = targets(feature.mayDependOn ?? []);
    const denied = targets(feature.mustNotDependOn ?? []);
    if (allowed.length > 0) policies.push(featurePolicy(feature.folder, 'allow', allowed));
    if (denied.length > 0) policies.push(featurePolicy(feature.folder, 'disallow', denied));
  }
  return policies;
}

function featurePolicy(fromFolder, verdict, toFolders) {
  return {
    from: { element: { type: ElementTypes.features, captured: { [FEATURE_CAPTURE]: fromFolder } } },
    [verdict]: { to: { element: { type: ElementTypes.features, captured: toFolders.map((folder) => ({ [FEATURE_CAPTURE]: folder })) } } },
  };
}
